<#
Creates the canonical DataCamp course scaffold for:

    Data Manipulation in SQL

Canonical folder:

    D:\Workarea\StudyBook\study_maps\DataCamp\courses\data_manipulation_in_sql

The script creates all course folders, stub files, a course-local lab, and an
embedded copy of the shared HTML templates. Existing files are preserved by
default. Use -Force only when you intentionally want to replace scaffolded files.

Run:

    .\scaffold_data_manipulation_in_sql.ps1
#>

[CmdletBinding()]
param(
    [string]$CourseName = 'Data Manipulation in SQL',

    [ValidatePattern('^[a-z0-9]+(?:_[a-z0-9]+)*$')]
    [string]$CourseSlug = 'data_manipulation_in_sql',

    [string]$TrackName = 'SQL Fundamentals',

    [ValidateRange(1, 999)]
    [int]$TrackPosition = 4,

    [string[]]$Chapters = @(
        "We'll take the CASE",
        'Short and Simple Subqueries',
        'Correlated Queries, Nested Queries, and Common Table Expressions',
        'Window Functions'
    ),

    [string]$DataCampRoot = 'D:\Workarea\StudyBook\study_maps\DataCamp',

    [ValidatePattern('^[a-z0-9_]+\.html$')]
    [string]$QuickLookupName = 'sql_quick_lookup.html',

    [switch]$Force
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function ConvertTo-Slug {
    param([Parameter(Mandatory)][string]$Text)

    $slug = $Text.ToLowerInvariant()
    $slug = $slug -replace "['’]", ''
    $slug = $slug -replace '[^a-z0-9]+', '_'
    $slug = $slug.Trim('_')

    if ([string]::IsNullOrWhiteSpace($slug)) {
        throw "Could not create a slug from: $Text"
    }

    return $slug
}

function Write-SafeFile {
    param(
        [Parameter(Mandatory)][string]$Path,
        [AllowEmptyString()][string]$Content = ''
    )

    if ((Test-Path -LiteralPath $Path) -and -not $Force) {
        Write-Host "KEEP     $Path" -ForegroundColor DarkYellow
        return
    }

    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    Set-Content -LiteralPath $Path -Value $Content -Encoding UTF8
    Write-Host "CREATED  $Path" -ForegroundColor Green
}

function Write-EmbeddedTemplate {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Base64
    )

    if ((Test-Path -LiteralPath $Path) -and -not $Force) {
        Write-Host "KEEP     $Path" -ForegroundColor DarkYellow
        return
    }

    $parent = Split-Path -Parent $Path
    if (-not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }

    [System.IO.File]::WriteAllBytes($Path, [System.Convert]::FromBase64String($Base64))
    Write-Host "CREATED  $Path" -ForegroundColor Green
}

function Expand-Template {
    param(
        [Parameter(Mandatory)][string]$TemplatePath,
        [Parameter(Mandatory)][hashtable]$Replacements
    )

    $content = Get-Content -LiteralPath $TemplatePath -Raw
    foreach ($key in $Replacements.Keys) {
        $content = $content.Replace("{{$key}}", [string]$Replacements[$key])
    }
    return $content
}

function New-LabGuideHtml {
    param([Parameter(Mandatory)][string]$Title)

@"
