    * { box-sizing:border-box; }
    body { margin:0; font-family:"Segoe UI",Arial,sans-serif; background:var(--bg); color:var(--text); line-height:1.6; }
    main { width:min(1000px,calc(100% - 32px)); margin:0 auto; padding:28px 0 48px; }
    section { background:var(--panel); border:1px solid var(--border); border-radius:14px; padding:22px; margin-bottom:18px; }
    h1,h2 { margin-top:0; }
