    a { color:var(--green); text-decoration:none; font-weight:700; }
    code,pre { font-family:Consolas,"Courier New",monospace; }
    pre { overflow:auto; padding:14px; border:1px solid var(--border); border-radius:9px; background:#0f141a; }
  </style>
</head>
<body>
  <main>
    <section>
      <h1>$Title Lab Guide</h1>
      <p><strong>Status:</strong> Scaffolded — practice evidence not yet recorded.</p>
      <p>This course warrants a real SQL lab because CASE expressions, subqueries, CTEs, and window functions require repeated query-writing practice.</p>
      <p><a href="../index.html">Back to Course Home</a></p>
    </section>
    <section>
      <h2>Planned Lab Sequence</h2>
      <ol>
        <li>Create the schema and sample soccer-style tables.</li>
        <li>Practice CASE expressions and conditional aggregation.</li>
        <li>Practice subqueries in SELECT, FROM, and WHERE.</li>
        <li>Practice correlated and nested subqueries plus CTEs.</li>
        <li>Practice window functions, running totals, and partitioned averages.</li>
      </ol>
    </section>
    <section>
      <h2>SQL Files</h2>
      <ul>
        <li><a href="sql/00_create_schema.sql">00_create_schema.sql</a></li>
        <li><a href="sql/01_create_tables.sql">01_create_tables.sql</a></li>
        <li><a href="sql/02_insert_sample_data.sql">02_insert_sample_data.sql</a></li>
        <li><a href="sql/03_case_expressions.sql">03_case_expressions.sql</a></li>
        <li><a href="sql/04_subqueries.sql">04_subqueries.sql</a></li>
        <li><a href="sql/05_correlated_nested_ctes.sql">05_correlated_nested_ctes.sql</a></li>
        <li><a href="sql/06_window_functions.sql">06_window_functions.sql</a></li>
      </ul>
    </section>
  </main>
</body>
</html>
"@
}

$courseRoot = Join-Path $DataCampRoot "courses\$CourseSlug"
