    $chapterFile = "chapter_${numberText}_${chapterSlug}_field_guide.html"

    $replacements = @{
        'SECTION_NUMBER' = "Chapter $chapterNumber"
        'SECTION_TITLE' = $chapterName
        'COURSE_TITLE' = $CourseName
        'PROJECT_HOME_LABEL' = 'DataCamp StudyBook'
        'SECTION_SUMMARY_HTML' = 'Under construction. This chapter guide will be populated from the DataCamp videos, exercises, transcripts, and learner notes.'
        'MAIN_FIELD_GUIDE_FILE' = 'field_guide.html'
        'QUICK_LOOKUP_FILE' = $QuickLookupName
        'NEXT_SECTION_FILE' = '#'
        'NEXT_SECTION_LABEL' = 'Next Chapter'
    }

    $chapterContent = Expand-Template -TemplatePath $sectionTemplate -Replacements $replacements
    Write-SafeFile -Path (Join-Path $studyRoot $chapterFile) -Content $chapterContent

    $chapterRecords += [pscustomobject]@{
        Number = $chapterNumber
        NumberText = $numberText
        Name = $chapterName
        Slug = $chapterSlug
        File = $chapterFile
    }
}

$fieldGuideContent = Expand-Template -TemplatePath $fieldGuideTemplate -Replacements @{
    'COURSE_TITLE' = $CourseName
    'PROJECT_HOME_LABEL' = 'DataCamp StudyBook'
    'PLATFORM_LABEL' = 'DataCamp'
    'COURSE_SUMMARY_HTML' = 'Whole-course memory map for CASE expressions, subqueries, common table expressions, and window functions.'
